function decodeBase64Floats(b64) {
  const buf = Uint8Array.from(atob(b64), c => c.charCodeAt(0)).buffer;
  return new Float32Array(buf);
}
function decodeBase64U32(b64) {
  const buf = Uint8Array.from(atob(b64), c => c.charCodeAt(0)).buffer;
  return new Uint32Array(buf);
}

